CREATE FUNCTION public.array_to_names(ids integer[]) RETURNS text
    LANGUAGE sql STABLE
    AS $$
    SELECT string_agg(pc.name, ', ' ORDER BY pc.name)
    FROM unnest(ids) AS _id
    JOIN persons_and_collectives pc ON pc.id = _id;
$$;


