--
-- Name: check_person_references(); Type: FUNCTION; Schema: public; Owner: schulbert
--

CREATE FUNCTION public.check_person_references() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    invalid_composers integer[];
    invalid_artists integer[];
BEGIN
    IF NEW.composer_ids IS NOT NULL THEN
        SELECT array_agg(id) INTO invalid_composers
        FROM unnest(NEW.composer_ids) AS id
        WHERE NOT EXISTS (SELECT 1 FROM persons_and_collectives pc WHERE pc.id = id);
        
        IF invalid_composers IS NOT NULL THEN
            RAISE EXCEPTION 'Недопустимые ID композиторов: %', invalid_composers;
        END IF;
    END IF;
    
    IF NEW.artist_ids IS NOT NULL THEN
        SELECT array_agg(id) INTO invalid_artists
        FROM unnest(NEW.artist_ids) AS id
        WHERE NOT EXISTS (SELECT 1 FROM persons_and_collectives pc WHERE pc.id = id);
        
        IF invalid_artists IS NOT NULL THEN
            RAISE EXCEPTION 'Недопустимые ID исполнителей: %', invalid_artists;
        END IF;
    END IF;
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.check_person_references() OWNER TO schulbert;

--
-- Name: correct_duplicates(integer, integer); Type: FUNCTION; Schema: public; Owner: schulbert
--

CREATE FUNCTION public.correct_duplicates(keep_id integer, remove_id integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    keep_name text;
    remove_name text;
    updated_composers integer;
    updated_artists integer;
BEGIN
    -- 1. Проверка: оба ID должны существовать
    SELECT name INTO keep_name FROM persons_and_collectives WHERE id = keep_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ID % не найден в persons_and_collectives', keep_id;
    END IF;

    SELECT name INTO remove_name FROM persons_and_collectives WHERE id = remove_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'ID % не найден в persons_and_collectives', remove_id;
    END IF;

    -- 2. Проверка: ID должны различаться
    IF keep_id = remove_id THEN
        RAISE EXCEPTION 'ID должны различаться';
    END IF;

    RAISE NOTICE 'Объединяем: "%" (%) → "%" (%)',
        remove_name, remove_id, keep_name, keep_id;

    -- 3. Заменяем remove_id на keep_id в composer_ids
    --    array_agg(DISTINCT ...) убирает возможные дубликаты после замены
    WITH updated AS (
        SELECT
            playlist_id,
            track_number,
            (SELECT array_agg(DISTINCT new_id ORDER BY new_id)
             FROM (
                 SELECT CASE WHEN elem = remove_id THEN keep_id ELSE elem END AS new_id
                 FROM unnest(composer_ids) AS elem
             ) sub
            ) AS new_composer_ids
        FROM tracks
        WHERE remove_id = ANY(composer_ids)
    )
    UPDATE tracks t
    SET composer_ids = u.new_composer_ids
    FROM updated u
    WHERE t.playlist_id = u.playlist_id
      AND t.track_number = u.track_number;

    GET DIAGNOSTICS updated_composers = ROW_COUNT;

    -- 4. То же самое для artist_ids
    WITH updated AS (
        SELECT
            playlist_id,
            track_number,
            (SELECT array_agg(DISTINCT new_id ORDER BY new_id)
             FROM (
                 SELECT CASE WHEN elem = remove_id THEN keep_id ELSE elem END AS new_id
                 FROM unnest(artist_ids) AS elem
             ) sub
            ) AS new_artist_ids
        FROM tracks
        WHERE remove_id = ANY(artist_ids)
    )
    UPDATE tracks t
    SET artist_ids = u.new_artist_ids
    FROM updated u
    WHERE t.playlist_id = u.playlist_id
      AND t.track_number = u.track_number;

    GET DIAGNOSTICS updated_artists = ROW_COUNT;

    -- 5. Удаляем дублирующую запись из справочника
    DELETE FROM persons_and_collectives WHERE id = remove_id;

    RAISE NOTICE 'Обновлено композиторов: %, исполнителей: %',
        updated_composers, updated_artists;
    RAISE NOTICE 'Удалена запись из справочника: "%" (id=%)', remove_name, remove_id;
END;
$$;


ALTER FUNCTION public.correct_duplicates(keep_id integer, remove_id integer) OWNER TO schulbert;

--
-- Name: prevent_person_delete_if_referenced(); Type: FUNCTION; Schema: public; Owner: schulbert
--

CREATE FUNCTION public.prevent_person_delete_if_referenced() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    ref_composers integer;
    ref_artists integer;
BEGIN
    -- Считаем, сколько треков ссылаются на удаляемую персону как на композитора
    SELECT COUNT(*) INTO ref_composers
    FROM tracks
    WHERE OLD.id = ANY(composer_ids);

    -- И как на исполнителя
    SELECT COUNT(*) INTO ref_artists
    FROM tracks
    WHERE OLD.id = ANY(artist_ids);

    IF ref_composers > 0 OR ref_artists > 0 THEN
        RAISE EXCEPTION 
            'Нельзя удалить "%" (id=%): на эту запись ссылаются треки (как на композитора: %, как на исполнителя: %). Сначала используйте correct_duplicates() или очистите массивы.',
            OLD.name, OLD.id, ref_composers, ref_artists;
    END IF;

    RETURN OLD;
END;
$$;


ALTER FUNCTION public.prevent_person_delete_if_referenced() OWNER TO schulbert;

