--
-- Name: rich_tracks; Type: VIEW; Schema: public; Owner: schulbert
--

CREATE VIEW public.rich_tracks AS
 SELECT t.playlist_id,
    t.track_number,
    p.name AS playlist_name,
    t.title,
    public.array_to_names(t.composer_ids) AS composers,
    public.array_to_names(t.artist_ids) AS artists,
    a.name AS album,
    a.release_year
   FROM ((public.tracks t
     LEFT JOIN public.playlists p ON ((t.playlist_id = p.id)))
     LEFT JOIN public.albums a ON ((t.album_id = a.id)));


ALTER VIEW public.rich_tracks OWNER TO schulbert;

--
-- Name: unprocessed_playlists; Type: VIEW; Schema: public; Owner: schulbert
--

CREATE VIEW public.unprocessed_playlists AS
 SELECT p.id AS playlist_id,
    p.name,
    count(p.id) AS total_tracks,
    count(*) FILTER (WHERE ((t.artist_ids IS NULL) AND (t.composer_ids IS NULL))) AS unprocessed_tracks
   FROM (public.playlists p
     LEFT JOIN public.tracks t ON ((t.playlist_id = p.id)))
  GROUP BY p.id, p.name
 HAVING ((count(*) FILTER (WHERE ((t.artist_ids IS NULL) AND (t.composer_ids IS NULL))) > 0) OR (count(p.id) = 0))
  ORDER BY p.id;


ALTER VIEW public.unprocessed_playlists OWNER TO schulbert;

